changeSet.sql:

create or alter function [graph].[GetPathByAssetId]
(
	@id bigint,
	@levelDelimiter nvarchar(50),
	@keyDelimiter nvarchar(50)
)
returns nvarchar(max)
as
begin
	declare @segments xml

	select @segments = Segments from graph.AssetNode where ID = @id;

	declare @path nvarchar(max)

	select	@path = string_agg(V, @levelDelimiter)
	from	(
			select	string_agg(Val, @keyDelimiter) within group(order by P) as  V
			from	(
					select	X.p.value('./@level', 'int') as L,
							X.p.value('./@position', 'int') as P,
							X.p.value('.', 'nvarchar(250)') as Val
					from	@segments.nodes('/path/segment') X(p)
					) O
			group by L
			) O

	return @path
end
